package com.taylordproductivty.med_timing_tracker.data

sealed class DoseTimingResult {
    object Eligible : DoseTimingResult()
    data class TooSoon(val minutesRemaining: Long) : DoseTimingResult()
}

object DoseTimingCalculator {
    // The next time this medication may be given again, or null if it has no minimum interval.
    fun computeNextEligible(givenAtEpochMillis: Long, minIntervalMinutes: Int?): Long? {
        if (minIntervalMinutes == null) return null
        return givenAtEpochMillis + minIntervalMinutes * 60_000L
    }

    // Eligible when there is no prior dose, no minimum interval configured, or the
    // candidate time is at or after the computed next-eligible time.
    fun evaluateTiming(
        candidateEpochMillis: Long,
        mostRecentDose: DoseLog?,
        minIntervalMinutes: Int?,
    ): DoseTimingResult {
        if (mostRecentDose == null || minIntervalMinutes == null) return DoseTimingResult.Eligible
        val nextEligible = computeNextEligible(mostRecentDose.givenAtEpochMillis, minIntervalMinutes)
            ?: return DoseTimingResult.Eligible
        if (candidateEpochMillis >= nextEligible) return DoseTimingResult.Eligible
        val minutesRemaining = (nextEligible - candidateEpochMillis + 59_999L) / 60_000L
        return DoseTimingResult.TooSoon(minutesRemaining)
    }
}
